import assert from 'node:assert/strict';
import test from 'node:test';
import { fetchStatus } from '../src/status-service.mjs';
test('reviewer: zero arguments and stop at first success with identical return object', async () => {
  const seen = []; const value = { ready: true };
  const actual = await fetchStatus((...args) => { seen.push(args); return value; });
  assert.strictEqual(actual, value); assert.deepEqual(seen, [[]]);
});
test('reviewer: two failures then third success with zero arguments and no fourth call', async () => {
  const seen = []; const value = { ready: true };
  const actual = await fetchStatus((...args) => {
    seen.push(args); if (seen.length < 3) return Promise.reject(new Error('temporary ' + seen.length));
    return Promise.resolve(value);
  });
  assert.strictEqual(actual, value); assert.deepEqual(seen, [[], [], []]);
});
test('reviewer: at most three failures and final error identity preserved', async () => {
  const seen = []; const errors = [new Error('first'), new Error('second'), new Error('third')];
  await assert.rejects(fetchStatus((...args) => { seen.push(args); throw errors[seen.length - 1]; }), error => error === errors[2]);
  assert.deepEqual(seen, [[], [], []]);
});
